<template><view class="page"><view class="content"><view class="card"><view class="card-title">深度个性化需求</view><view class="sub intro">一位旅行设计师全程跟进，48 小时内出具专属方案。</view><view class="form-item" v-for="f in inputs" :key="f.label"><view class="label">{{f.label}}</view><input class="input" :placeholder="f.placeholder"/></view><view class="form-item"><view class="label">特殊需求</view><view class="choices"><view v-for="t in tags" :key="t" class="choice" :class="{on:selected.includes(t)}" @click="toggle(t)">{{t}}</view></view></view><view class="form-item"><view class="label">补充说明</view><textarea class="input textarea" placeholder="例如：想看日出、住宿要安静、有人不能吃辣……"/></view></view></view><view class="fixed-action"><view class="btn btn-primary" @click="submit">提交定制需求</view></view></view></template><script setup>import{ref}from'vue';const inputs=[{label:'想去哪里',placeholder:'可填写多个目的地或“还没想好”'},{label:'出行时间',placeholder:'请选择预计出发日期'},{label:'旅行天数',placeholder:'例如：5 天 4 夜'},{label:'人均积分预算',placeholder:'例如：3000-5000 积分'},{label:'出行人数',placeholder:'请输入人数'}];const tags=['毕业团建','纪念日','小众路线','亲子同行','摄影旅拍'];const selected=ref([]);const toggle=t=>selected.value.includes(t)?selected.value.splice(selected.value.indexOf(t),1):selected.value.push(t);const submit=()=>uni.showModal({title:'需求提交成功',content:'旅行社将在 48 小时内出具专属方案，请在消息通知中查看。',showCancel:false,success:()=>uni.redirectTo({url:'/pages/custom/preview'})})</script><style scoped>.intro{line-height:1.7;margin:-8rpx 0 30rpx}</style>
